<script setup>
import {computed,inject,ref,watch} from 'vue'
import {api} from '../api.js'
const cal=inject('calibration'),work=inject('workspace'),id=ref(''),reason=ref(''),clean=ref(''),mapping=ref(''),json=ref('{}'),error=ref('')
const samples=computed(()=>cal.state.dataset?.samples.filter(s=>s.partition==='CALIBRATION')||[])
watch(id,value=>{const s=samples.value.find(s=>s.sample_id===value);if(s)json.value=JSON.stringify({retrieved_evidence:s.retrieved_evidence,reference_policy:s.reference_policy,reference_complete:s.reference_complete,context:s.context},null,2)})
async function save(){error.value='';try{const corrections=JSON.parse(json.value);await cal.act('创建派生取证输入',async()=>{const result=await api.post(`/calibration/datasets/${cal.state.dataset.dataset_id}/derived-inputs`,{sample_id:id.value,corrections,reason:reason.value,cleaning_version:clean.value,semantic_mapping_version:mapping.value,actor:cal.state.actor});await cal.refresh();await cal.openDataset(result.dataset_id);cal.go(3);work.state.notice='已创建带父引用的新输入；原问题与回答保留，旧人标不自动继承。请按用途重新复核。'})}catch(e){error.value=e.message||'输入不符合派生规则'}}
</script>
<template><details class="panel"><summary>数据取证修复：创建派生输入（固定原回答）</summary><p>用于修正解析、证据关联或补证。原记录不覆盖；问题和实际回答禁止修改。新输入保存父版本、清洗与映射版本，旧人工参照不自动继承。保留题不能从此入口改写。</p><p v-if="error" role="alert" class="note danger">{{error}}</p><label>要修复的校准样本<select v-model="id"><option value="">选择样本</option><option v-for="s in samples" :key="s.sample_id" :value="s.sample_id">{{s.question}}</option></select></label><label>取证修正 JSON<textarea v-model="json" rows="12" spellcheck="false" /></label><label>修正理由与原始依据<textarea v-model="reason" rows="2" required /></label><div class="form-row"><label>清洗版本<input v-model="clean" placeholder="填写实际版本，不自动补写" /></label><label>语义映射版本<input v-model="mapping" /></label></div><button class="primary" :disabled="!id||!reason.trim()||!clean.trim()||!mapping.trim()||!!work.state.busy" @click="save">保存为派生输入并重新复核</button></details></template>
